import{_ as n,o as t,c as a,ag as i}from"./chunks/framework.CrXGS008.js";const h=JSON.parse('{"title":"Berechtigungen","description":"","frontmatter":{},"headers":[],"relativePath":"de/nay-lib/permissions.md","filePath":"de/nay-lib/permissions.md"}'),d={name:"de/nay-lib/permissions.md"};function s(r,e,o,c,l,p){return t(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="berechtigungen" tabindex="-1">Berechtigungen <a class="header-anchor" href="#berechtigungen" aria-label="Permalink to &quot;Berechtigungen&quot;">​</a></h1><p>Jede Nayretis Aktion, die Rechte braucht, prüft einen <strong>Scope</strong>. Scopes vergibst du per ACE, mit Regeln in der Datenbank oder im Tab <strong>Berechtigungen</strong> von <code>/nay</code>.</p><h2 id="scopes" tabindex="-1">Scopes <a class="header-anchor" href="#scopes" aria-label="Permalink to &quot;Scopes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scope</th><th>Gewährt</th></tr></thead><tbody><tr><td><code>nay.admin</code></td><td>Alles: jedes Skript, die Nayretis Einstellungen, Berechtigungen, API-Tokens, Webhooks und das Protokoll.</td></tr><tr><td><code>nay.config</code></td><td>Die Einstellungen aller Skripte.</td></tr><tr><td><code>nay.audit</code></td><td>Das Protokoll.</td></tr><tr><td><code>&lt;resource&gt;.config</code></td><td>Die Einstellungen eines Skripts, zum Beispiel <code>nay_car_wash.config</code>.</td></tr><tr><td><code>&lt;resource&gt;.&lt;name&gt;</code></td><td>Eine Berechtigung, die ein Skript festlegt, aufgeführt auf seiner Seite.</td></tr><tr><td><code>&lt;resource&gt;.*</code></td><td>Jeder Scope eines Skripts. Funktioniert mit Regeln (<code>nay_grant</code>), nicht mit ACE.</td></tr></tbody></table><h2 id="mit-ace" tabindex="-1">Mit ACE <a class="header-anchor" href="#mit-ace" aria-label="Permalink to &quot;Mit ACE&quot;">​</a></h2><p>Ein ACE auf einen Scope gewährt ihn. Vergib jeden Scope mit seinem vollständigen Namen (Scopes mit Platzhalter wie <code>nay_car_wash.*</code> funktionieren nur als Regeln). In der <code>server.cfg</code>:</p><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>add_ace group.admin nay.admin allow</span></span>
<span class="line"><span>add_ace group.mod nay_car_wash.config allow</span></span></code></pre></div><h2 id="mit-regeln" tabindex="-1">Mit Regeln <a class="header-anchor" href="#mit-regeln" aria-label="Permalink to &quot;Mit Regeln&quot;">​</a></h2><p>Regeln werden in der Datenbank gespeichert und können einen Spieler direkt betreffen. Eine Regel hat einen Typ, eine Kennung und einen Scope. Die Typen sind:</p><ul><li><code>ace</code>: jeder Spieler, der für dieses ACE-Objekt berechtigt ist;</li><li><code>discord</code>, <code>steam</code>, <code>fivem</code>, <code>license</code>: ein einzelner Spieler, über seine Kennung.</li></ul><p>Über die Serverkonsole:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nay_grant license 1a2b3c4d5e6f nay.admin</span></span>
<span class="line"><span>nay_grant discord 123456789012345678 nay_car_wash.config</span></span>
<span class="line"><span>nay_revoke discord 123456789012345678 nay_car_wash.config</span></span>
<span class="line"><span>nay_rules</span></span></code></pre></div><p><code>nay_grant</code> und <code>nay_revoke</code> erwarten <code>&lt;ace|discord|steam|fivem|license&gt; &lt;identifier&gt; &lt;scope&gt;</code>. <code>nay_rules</code> listet jede Regel mit ihrer Nummer auf.</p><p>Im Spiel listet der Tab <strong>Berechtigungen</strong> von <code>/nay</code> (Scope <code>nay.admin</code>) dieselben Regeln auf, fügt sie hinzu und entfernt sie. Jede Änderung wird ins <a href="/de/nay-lib/audit">Protokoll</a> geschrieben.</p>`,14)])])}const u=n(d,[["render",s]]);export{h as __pageData,u as default};
